<?php
namespace App\Domain\Industries;use App\Domain\PublicChrome\{PublicAssetPath,PublicLink};use App\Models\Industry;use Illuminate\Support\Facades\Cache;use Throwable;final class IndustryViewData{public function published(string $slug):?array{try{$industry=Industry::publiclyVisible()->where('slug',$slug)->first();if(!$industry){return null;}return Cache::remember("public.industries.v1.$industry->id.$slug.".IndustryCache::version($industry->id),now()->addMinutes(15),fn()=>$this->transform($this->load($industry),false));}catch(Throwable){return $this->direct($slug);}}public function preview(Industry $industry):array{return $this->transform($this->load($industry),true);}private function load(Industry $industry):Industry{return $industry->load(['category','challenges'=>fn($q)=>$q->orderBy('display_order')->limit(12),'outcomes'=>fn($q)=>$q->orderBy('display_order')->limit(12),'needs'=>fn($q)=>$q->orderBy('display_order')->limit(12),'useCases'=>fn($q)=>$q->orderBy('display_order')->limit(12),'relatedSolutions'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedProducts'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedPages'=>fn($q)=>$q->publiclyVisible()->limit(6)]);}private function transform(Industry $industry,bool $preview):array{$children=fn($items)=>$items->filter(fn($item)=>$preview||$item->is_active)->map(fn($item)=>['title'=>$item->title,'description'=>$item->description,'icon'=>in_array($item->icon,IndustryRegistry::ICONS,true)?$item->icon:null])->values()->all();$related=fn($items,string $route)=>$items->map(fn($item)=>['title'=>$item->title,'description'=>$item->short_description??null,'url'=>route($route,$item->slug)])->all();return ['title'=>$industry->title,'slug'=>$industry->slug,'eyebrow'=>$industry->eyebrow,'short_description'=>$industry->short_description,'overview'=>$industry->overview,'challenge_summary'=>$industry->challenge_summary,'outcome_summary'=>$industry->outcome_summary,'image'=>PublicAssetPath::isSafe($industry->featured_image_path)?$industry->featured_image_path:null,'image_alt'=>$industry->featured_image_alt,'category'=>$industry->category&&$industry->category->is_active?['name'=>$industry->category->name,'slug'=>$industry->category->slug]:null,'challenges'=>$children($industry->challenges),'outcomes'=>$children($industry->outcomes),'needs'=>$children($industry->needs),'use_cases'=>$children($industry->useCases),'related_solutions'=>$related($industry->relatedSolutions,'solutions.show'),'related_products'=>$related($industry->relatedProducts,'products.show'),'related_pages'=>$related($industry->relatedPages,'pages.show'),'primary_cta'=>$this->link($industry->primary_cta_label,$industry->primary_cta_url),'secondary_cta'=>$this->link($industry->secondary_cta_label,$industry->secondary_cta_url),'meta_title'=>$industry->meta_title?:$industry->title,'meta_description'=>$industry->meta_description?:$industry->short_description,'og_title'=>$industry->og_title?:($industry->meta_title?:$industry->title),'og_description'=>$industry->og_description?:($industry->meta_description?:$industry->short_description),'og_image'=>PublicAssetPath::isSafe($industry->og_image_path)?$industry->og_image_path:null,'canonical_url'=>$industry->canonical_url,'robots'=>$preview?'noindex, nofollow':(($industry->robots_index?'index':'noindex').', '.($industry->robots_follow?'follow':'nofollow'))];}private function direct(string $slug):?array{try{$industry=Industry::publiclyVisible()->where('slug',$slug)->first();return $industry?$this->transform($this->load($industry),false):null;}catch(Throwable){return null;}}private function link(?string $label,?string $url):?array{return $label&&$url&&PublicLink::isSafeUrl($url)?['label'=>$label,'url'=>$url]:null;}}
